function registerComfyUINativeNode(def) {
  const existing = registry.get(def.class_name)?.spec;
  if (existing && existing.kind && existing.kind !== "native") {
    return false;
  }
  const inputs = [];
  for (const key of Object.keys(def.input?.required ?? {})) {
    inputs.push({ name: key, type: "ANY" });
  }
  const outputs = (def.output ?? []).map((o, i) => ({
    name: def.output_name?.[i] ?? o,
    type: normalizeNativeType(o)
  }));
  const widgets = Object.entries(def.input?.required ?? {}).map(([name, [type, opts]]) => ({
    name,
    type,
    default: opts?.default,
    options: type === "COMBO" ? opts?.values : void 0
  }));
  return registerNodeSpec({
    type: def.class_name,
    kind: "native",
    title: def.display_name ?? def.class_name,
    category: def.category ?? "comfyUI",
    inputs,
    outputs,
    widgets,
    color: "#f59e0b"
  });
}
function comfyTVKindOutputType(kind) {
  switch (kind) {
    case "image":
    case "image-batch":
    case "image-picker":
    case "panorama":
      return "COMFYTV_IMAGES";
    case "video":
    case "video-picker":
      return "COMFYTV_VIDEO";
    case "audio":
    case "audio-picker":
      return "COMFYTV_AUDIO";
    case "text":
      return "COMFYTV_TEXT";
    case "model":
      return "COMFYTV_MODEL";
    case "material":
      return "COMFYTV_MATERIAL";
    case "storyboard":
      return "COMFYTV_STORYBOARD";
    case "timeline":
      return "COMFYTV_TIMELINE";
    case "project":
      return "COMFYTV_JSON";
    default:
      return "COMFYTV_IMAGE";
  }
}
