function normalizePortType(t) {
  switch (t) {
    case "IMAGE":
    case "image":
      return "IMAGE";
    case "VIDEO":
    case "video":
      return "VIDEO";
    case "AUDIO":
    case "audio":
      return "AUDIO";
    case "TEXT":
    case "text":
      return "TEXT";
    case "SAROS_JSON":
    case "json":
      return "SAROS_JSON";
    default:
      return "ANY";
  }
}
function normalizeNativeType(t) {
  const lower = t.toLowerCase();
  if (lower.includes("image")) {
    return "IMAGE";
  }
  if (lower.includes("video")) {
    return "VIDEO";
  }
  if (lower.includes("audio")) {
    return "AUDIO";
  }
  if (lower.includes("string") || lower.includes("text")) {
    return "TEXT";
  }
  return "ANY";
}

