var usePicklistStore = create((set, get2) => ({
  skills: [],
  skillsLoaded: false,
  loadSkills: async () => {
    if (get2().skillsLoaded && get2().skills.length > 0) {
      return;
    }
    try {
      const skills = await sendRequest("skills.list", {});
      set({ skills: skills ?? [], skillsLoaded: (skills ?? []).length > 0 });
    } catch {
      set({ skillsLoaded: false });
    }
  },
  tools: [],
  toolsLoaded: false,
  loadTools: async () => {
    if (get2().toolsLoaded) {
      return;
    }
    try {
      const tools = await sendRequest("tools.list", {});
      set({ tools: tools ?? [], toolsLoaded: true });
    } catch {
      set({ toolsLoaded: true });
    }
  }
}));

