var ALIGN_FACTOR = {
  left: { axis: "x", f: 0 },
  hcenter: { axis: "x", f: 0.5 },
  right: { axis: "x", f: 1 },
  top: { axis: "y", f: 0 },
  vcenter: { axis: "y", f: 0.5 },
  bottom: { axis: "y", f: 1 }
};
function isAlignOp(op) {
  return op in ALIGN_FACTOR;
}
function unionRect(rects) {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const r of rects) {
    minX = Math.min(minX, r.x);
    minY = Math.min(minY, r.y);
    maxX = Math.max(maxX, r.x + r.w);
    maxY = Math.max(maxY, r.y + r.h);
  }
  if (!isFinite(minX)) {
    return { x: 0, y: 0, w: 0, h: 0 };
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}
function anchorOf(r, axis, f) {
  return axis === "x" ? r.x + r.w * f : r.y + r.h * f;
}
function align(rects, op, reference) {
  const { axis, f } = ALIGN_FACTOR[op];
  if (rects.length === 0) {
    return [];
  }
  const ref = reference ?? unionRect(rects);
  const target = anchorOf(ref, axis, f);
  return rects.map((r) => {
    const d = target - anchorOf(r, axis, f);
    return axis === "x" ? { dx: d, dy: 0 } : { dx: 0, dy: d };
  });
}
function distribute(rects, op) {
  const zero = rects.map(() => ({ dx: 0, dy: 0 }));
  if (rects.length < 3) {
    return zero;
  }
  const axis = op === "hspread" || op === "hgap" ? "x" : "y";
  const size = (r) => axis === "x" ? r.w : r.h;
  const pos2 = (r) => axis === "x" ? r.x : r.y;
  const order = rects.map((r, i) => ({ r, i })).sort((a, b) => op === "hgap" || op === "vgap" ? pos2(a.r) - pos2(b.r) : anchorOf(a.r, axis, 0.5) - anchorOf(b.r, axis, 0.5));
  const out = zero;
  const first = order[0];
  const last = order[order.length - 1];
  if (op === "hspread" || op === "vspread") {
    const a0 = anchorOf(first.r, axis, 0.5);
    const a1 = anchorOf(last.r, axis, 0.5);
    const fill = (a1 - a0) / (order.length - 1);
    for (let n2 = 1; n2 < order.length - 1; n2++) {
      const { r, i } = order[n2];
      const d = a0 + n2 * fill - anchorOf(r, axis, 0.5);
      out[i] = axis === "x" ? { dx: d, dy: 0 } : { dx: 0, dy: d };
    }
    return out;
  }
  let midSizes = 0;
  for (let n2 = 1; n2 < order.length - 1; n2++) {
    midSizes += size(order[n2].r);
  }
  const span = pos2(last.r) - (pos2(first.r) + size(first.r));
  const gap = (span - midSizes) / (order.length - 1);
  let z = pos2(first.r) + size(first.r);
  for (let n2 = 1; n2 < order.length - 1; n2++) {
    const { r, i } = order[n2];
    const d = z + gap - pos2(r);
    out[i] = axis === "x" ? { dx: d, dy: 0 } : { dx: 0, dy: d };
    z += gap + size(r);
  }
  return out;
}
function arrange(rects, op, reference) {
  return isAlignOp(op) ? align(rects, op, reference) : distribute(rects, op);
}
function clampNum(v2, lo, hi) {
  return Math.max(lo, Math.min(hi, v2));
}
function buildSnapTargets(otherRects, bounds, extras) {
  const bw = bounds?.w ?? 1;
  const bh = bounds?.h ?? 1;
  const xs = [0, bw / 2, bw];
  const ys = [0, bh / 2, bh];
  for (const r of otherRects) {
    xs.push(r.x, r.x + r.w / 2, r.x + r.w);
    ys.push(r.y, r.y + r.h / 2, r.y + r.h);
  }
  if (extras?.gridX && extras.gridX > 0) {
    for (let v2 = 0; v2 <= bw + 1e-9; v2 += extras.gridX) {
      xs.push(v2);
    }
  }
  if (extras?.gridY && extras.gridY > 0) {
    for (let v2 = 0; v2 <= bh + 1e-9; v2 += extras.gridY) {
      ys.push(v2);
    }
  }
  for (const g of extras?.guideXs ?? []) {
    xs.push(g);
  }
  for (const g of extras?.guideYs ?? []) {
    ys.push(g);
  }
  return { xs, ys };
}
function nearestTarget(val, targets, thr) {
  let best = null;
  let bd = thr;
  for (const t of targets) {
    const dd = Math.abs(val - t);
    if (dd < bd) {
      bd = dd;
      best = t;
    }
  }
  return best;
}
function overlaps(a0, a1, b0, b1) {
  return a0 < b1 && a1 > b0;
}
function eqCandidatesAxis(rect, others, axis) {
  const p = (r) => axis === "x" ? r.x : r.y;
  const s = (r) => axis === "x" ? r.w : r.h;
  const c0 = (r) => axis === "x" ? r.y : r.x;
  const c1 = (r) => axis === "x" ? r.y + r.h : r.x + r.w;
  const cross = axis === "x" ? rect.y + rect.h / 2 : rect.x + rect.w / 2;
  const near = others.filter((o) => overlaps(c0(o), c1(o), c0(rect), c1(rect)));
  const lefts = near.filter((o) => p(o) + s(o) <= p(rect) + s(rect) / 2).sort((a, b) => p(b) + s(b) - (p(a) + s(a)));
  const rights = near.filter((o) => p(o) >= p(rect) + s(rect) / 2).sort((a, b) => p(a) - p(b));
  const out = [];
  const L = lefts[0];
  const R = rights[0];
  if (L && R) {
    const free = p(R) - (p(L) + s(L)) - s(rect);
    if (free >= 0) {
      const pos2 = p(L) + s(L) + free / 2;
      out.push({
        pos: pos2,
        guide: { axis, pos: pos2, kind: "gap", cross, spans: [[p(L) + s(L), pos2], [pos2 + s(rect), p(R)]] }
      });
    }
  }
  if (lefts.length >= 2) {
    const L1 = lefts[0];
    const L2 = lefts[1];
    const gap = p(L1) - (p(L2) + s(L2));
    if (gap >= 0) {
      const pos2 = p(L1) + s(L1) + gap;
      out.push({
        pos: pos2,
        guide: { axis, pos: pos2, kind: "gap", cross, spans: [[p(L2) + s(L2), p(L1)], [p(L1) + s(L1), pos2]] }
      });
    }
  }
  if (rights.length >= 2) {
    const R1 = rights[0];
    const R2 = rights[1];
    const gap = p(R2) - (p(R1) + s(R1));
    if (gap >= 0) {
      const pos2 = p(R1) - gap - s(rect);
      out.push({
        pos: pos2,
        guide: { axis, pos: pos2, kind: "gap", cross, spans: [[pos2 + s(rect), p(R1)], [p(R1) + s(R1), p(R2)]] }
      });
    }
  }
  return out;
}
function applySnap(mode, rect, targets, opts) {
  let { x: x2, y, w, h } = rect;
  const guides = [];
  const { thrX, thrY, minWH } = opts;
  const bw = opts.boundsW ?? 1;
  const bh = opts.boundsH ?? 1;
  const clamp3 = opts.clamp !== false;
  if (mode === "move") {
    let bestDX = null;
    let guideX = null;
    for (const v2 of [x2, x2 + w / 2, x2 + w]) {
      const t = nearestTarget(v2, targets.xs, thrX);
      if (t != null) {
        const dd = t - v2;
        if (bestDX === null || Math.abs(dd) < Math.abs(bestDX)) {
          bestDX = dd;
          guideX = { axis: "x", pos: t, kind: "edge" };
        }
      }
    }
    let bestDY = null;
    let guideY = null;
    for (const v2 of [y, y + h / 2, y + h]) {
      const t = nearestTarget(v2, targets.ys, thrY);
      if (t != null) {
        const dd = t - v2;
        if (bestDY === null || Math.abs(dd) < Math.abs(bestDY)) {
          bestDY = dd;
          guideY = { axis: "y", pos: t, kind: "edge" };
        }
      }
    }
    if (opts.eqRects?.length) {
      for (const c of eqCandidatesAxis(rect, opts.eqRects, "x")) {
        const dd = c.pos - x2;
        if (Math.abs(dd) < thrX && (bestDX === null || Math.abs(dd) < Math.abs(bestDX))) {
          bestDX = dd;
          guideX = c.guide;
        }
      }
      for (const c of eqCandidatesAxis(rect, opts.eqRects, "y")) {
        const dd = c.pos - y;
        if (Math.abs(dd) < thrY && (bestDY === null || Math.abs(dd) < Math.abs(bestDY))) {
          bestDY = dd;
          guideY = c.guide;
        }
      }
    }
    if (bestDX !== null && guideX) {
      x2 += bestDX;
      guides.push(guideX);
    }
    if (bestDY !== null && guideY) {
      y += bestDY;
      guides.push(guideY);
    }
  } else {
    if (mode.includes("e")) {
      const t = nearestTarget(x2 + w, targets.xs, thrX);
      if (t != null) {
        w = t - x2;
        guides.push({ axis: "x", pos: t });
      }
    }
    if (mode.includes("w")) {
      const t = nearestTarget(x2, targets.xs, thrX);
      if (t != null) {
        const rt = x2 + w;
        x2 = t;
        w = rt - x2;
        guides.push({ axis: "x", pos: t });
      }
    }
    if (mode.includes("s")) {
      const t = nearestTarget(y + h, targets.ys, thrY);
      if (t != null) {
        h = t - y;
        guides.push({ axis: "y", pos: t });
      }
    }
    if (mode.includes("n")) {
      const t = nearestTarget(y, targets.ys, thrY);
      if (t != null) {
        const bt = y + h;
        y = t;
        h = bt - y;
        guides.push({ axis: "y", pos: t });
      }
    }
    w = Math.max(minWH, w);
    h = Math.max(minWH, h);
  }
  if (clamp3) {
    x2 = clampNum(x2, 0, Math.max(0, bw - w));
    y = clampNum(y, 0, Math.max(0, bh - h));
  }
  return { rect: { x: x2, y, w, h }, guides };
}

// src/features/workflowEditor/comfyHost/posterExecutor.ts
async function runPosterNode(input) {
  const render = input.store.byNode(input.snapshotKey ?? input.nodeId).find((e2) => e2.media.kind === "image");
  if (!render) {
    return { promptId: "", status: "error", error: "\u8BF7\u5148\u5728\u8282\u70B9\u5F39\u7A97\u4E2D\u6392\u7248\u5E76\u751F\u6210\u6D77\u62A5\u3002", entries: [] };
  }
  return { promptId: "", status: "success", entries: [render] };
}

